export class StringPalette {
    _count = 0;
    _palette = [];
    _map = {};
    constructor(inital) {
        if (inital) {
            const length = inital.length;
            for (let i = 0; i < length; i++) {
                this.register(inital[i]);
            }
        }
    }
    get size() {
        return this._count;
    }
    load(palette) {
        this._palette = [];
        this._map = {};
        const length = palette.length;
        for (let i = 0; i < length; i++) {
            this.register(palette[i]);
        }
    }
    register(string) {
        if (this._map[string] !== undefined)
            return this._map[string];
        const id = this._count;
        this._count++;
        this._palette[id] = string;
        this._map[string] = id;
        return id;
    }
    get() {
        return this._palette;
    }
    getMap() {
        return this._map;
    }
    isRegistered(id) {
        return this._map[id] !== undefined;
    }
    getNumberId(id) {
        return this._map[id];
    }
    getStringId(id) {
        return this._palette[id];
    }
}
